  KEY `ix_pt_enrollments_customer_id` (`customer_id`),
  KEY `ix_pt_enrollments_group_type` (`group_type`),
  KEY `ix_pt_enrollments_status` (`status`),
  CONSTRAINT `pt_enrollments_ibfk_1` FOREIGN KEY (`customer_id`) REFERENCES `customers` (`id`),
  CONSTRAINT `pt_enrollments_ibfk_2` FOREIGN KEY (`coach_id`) REFERENCES `employees` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
